    BaniLine(id = "kirtan-sohila-12", gurmukhi = "ਸਦਣਹਾਰਾ ਸਿਮਰੀਐ; ਨਾਨਕ. ਸੇ ਦਿਹ ਆਵੰਨਿ ॥੪॥੧॥", transliteration = "sadanhaaraa simreeai; naanak. se dih aavann ||4||1||", translation = "Remember in meditation the One who summons us; O Nanak, that day is drawing near! ||4||1||", hindi = "सदणहारा सिमरीऐ; नानक. से दिह आवंनि ॥४॥१॥", punjabi = "(ਹੇ ਸਤਸੰਗੀਓ!) ਉਸ ਸੱਦਾ ਭੇਜਣ ਵਾਲੇ ਪ੍ਰਭੂ-ਪਤੀ ਨੂੰ ਯਾਦ ਰੱਖਣਾ ਚਾਹੀਦਾ ਹੈ (ਕਿਉਂਕਿ) ਹੇ ਨਾਨਕ! (ਸਾਡੇ ਭੀ) ਉਹ ਦਿਨ (ਨੇੜੇ) ਆ ਰਹੇ ਹਨ ॥੪॥੧॥", wordMeaning = "ਸੇ ਦਿਹ = ਉਹ ਦਿਹਾੜੇ। ਆਵੰਨਿ = ਆਉਂਦੇ ਹਨ॥੪॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "kirtan-sohila-13", gurmukhi = "ਰਾਗੁ ਆਸਾ ਮਹਲਾ ੧ ॥", transliteration = "raag aasaa mahlaa 1 ||", translation = "Raag Aasaa, First Mehl:", hindi = "रागु आसा महला १ ॥", punjabi = "ਰਾਗ ਆਸਾ ਵਿੱਚ ਗੁਰੂ ਨਾਨਕ ਜੀ ਦੀ ਬਾਣੀ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "kirtan-sohila-14", gurmukhi = "ਛਿਅ ਘਰ, ਛਿਅ ਗੁਰ; ਛਿਅ ਉਪਦੇਸ ॥", transliteration = "chhia ghar, chhia gur; chhia updes ||", translation = "There are six schools of philosophy, six teachers, and six sets of teachings.", hindi = "छिअ घर, छिअ गुर; छिअ उपदेस ॥", punjabi = "(ਹੇ ਭਾਈ!) ਛੇ ਸ਼ਾਸਤਰ ਹਨ, ਛੇ ਹੀ (ਇਹਨਾਂ ਸ਼ਾਸਤਰਾਂ ਦੇ) ਚਲਾਣ ਵਾਲੇ ਹਨ, ਛੇ ਹੀ ਇਹਨਾਂ ਦੇ ਸਿੱਧਾਂਤ ਹਨ।", wordMeaning = "ਛਿਅ = ਛੇ। ਘਰ = ਸ਼ਾਸਤਰ {ਸਾਂਖ, ਨਿਆਇ, ਵੈਸ਼ੇਸ਼ਿਕ, ਯੋਗ, ਮੀਮਾਂਸਾ, ਵੇਦਾਂਤ}। ਗੁਰ = (ਇਹਨਾਂ ਸ਼ਾਸਤਰਾਂ ਦੇ) ਕਰਤਾ, {ਕਪਲ, ਗੋਤਮ, ਕਣਾਦ, ਪਤੰਜਲੀ, ਜੈਮਨੀ, ਵਿਆਸ}। ਉਪਦੇਸ = ਸਿੱਖਿਆ, ਸਿੱਧਾਂਤ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "kirtan-sohila-15", gurmukhi = "ਗੁਰੁ ਗੁਰੁ ਏਕੋ; ਵੇਸ ਅਨੇਕ ॥੧॥", transliteration = "gur gur eko; ves anek ||1||", translation = "But the Teacher of teachers is the One, who appears in so many forms. ||1||", hindi = "गुरु गुरु एको; वेस अनेक ॥१॥", punjabi = "ਪਰ ਇਹਨਾਂ ਸਾਰਿਆਂ ਦਾ ਮੂਲ-ਗੁਰੂ (ਪਰਮਾਤਮਾ) ਇੱਕ ਹੈ। (ਇਹ ਸਾਰੇ ਸਿਧਾਂਤ) ਉਸ ਇੱਕ ਪ੍ਰਭੂ ਦੇ ਹੀ ਅਨੇਕਾਂ ਵੇਸ ਹਨ (ਪ੍ਰਭੂ ਦੀ ਹਸਤੀ ਦੇ ਪਰਕਾਸ਼ ਦੇ ਰੂਪ ਹਨ) ॥੧॥", wordMeaning = "ਗੁਰੁ ਗੁਰੁ = ਇਸਟ ਪ੍ਰਭੂ। ਏਕੋ = ਇੱਕ ਹੀ। ਵੇਸ = ਰੂਪ॥੧॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "kirtan-sohila-16", gurmukhi = "ਬਾਬਾ, ਜੈ ਘਰਿ; ਕਰਤੇ ਕੀਰਤਿ ਹੋਇ ॥", transliteration = "baabaa, jai ghar; karte keerat hoi ||", translation = "O Baba: that system in which the Praises of the Creator are sung", hindi = "बाबा, जै घरि; करते कीरति होइ ॥", punjabi = "ਹੇ ਭਾਈ! ਜਿਸ (ਸਤਸੰਗ-) ਘਰ ਵਿਚ ਕਰਤਾਰ ਦੀ ਸਿਫ਼ਤ-ਸਾਲਾਹ ਹੁੰਦੀ ਹੈ,", wordMeaning = "ਬਾਬਾ = ਹੇ ਭਾਈ! ਜੈ ਘਰਿ = ਜਿਸ (ਸਤਸੰਗ-) ਘਰ ਵਿਚ। ਕਰਤੇ ਕੀਰਤਿ = ਕਰਤਾਰ ਦੀ ਸਿਫ਼ਤ-ਸਾਲਾਹ। ਹੋਇ = ਹੁੰਦੀ ਹੈ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "kirtan-sohila-17", gurmukhi = "ਸੋ ਘਰੁ ਰਾਖੁ; ਵਡਾਈ ਤੋਇ ॥੧॥ ਰਹਾਉ ॥", transliteration = "so ghar raakh; vdaaee toi ||1|| rhaau ||", translation = "-follow that system; in it rests true greatness. ||1||Pause||", hindi = "सो घरु राखु; वडाई तोइ ॥१॥ रहाउ ॥", punjabi = "ਉਸ ਘਰ ਨੂੰ ਸਾਂਭ ਰੱਖ (ਉਸ ਸਤਸੰਗ ਦਾ ਆਸਰਾ ਲਈ ਰੱਖ) ਇਸੇ ਵਿਚ ਤੇਰੀ ਭਲਾਈ ਹੈ ॥੧॥ ਰਹਾਉ ॥", wordMeaning = "ਰਾਖੁ = ਸੰਭਾਲ। ਤੋਇ = ਤੇਰੀ। ਵਡਾਈ = ਭਲਾਈ॥੧॥ਰਹਾਉ॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "kirtan-sohila-18", gurmukhi = "ਵਿਸੁਏ ਚਸਿਆ, ਘੜੀਆ ਪਹਰਾ; ਥਿਤੀ ਵਾਰੀ ਮਾਹੁ ਹੋਆ ॥", transliteration = "visue chsiaa, ghreeaa pahraa; thitee vaaree maah hoaa ||", translation = "The seconds, minutes and hours, days, weeks and months,", hindi = "विसुए चसिआ, घड़ीआ पहरा; थिती वारी माहु होआ ॥", punjabi = "ਜਿਵੇਂ ਵਿਸੁਏ, ਚਸੇ, ਘੜੀਆਂ, ਪਹਰ, ਥਿੱਤਾਂ, ਵਾਰ, ਮਹੀਨਾ (ਆਦਿਕ),", wordMeaning = "ਅੱਖ ਦੇ ੧੫ ਫੋਰ = ੧ ਵਿਸਾ।੧੫ ਵਿਸੁਏ = ੧ ਚਸਾ। ੩੦ ਚਸੇ = ੧ ਪਲ।੬੦ ਪਲ = ੧ ਘੜੀ। ਸਾਢੋ ੭ ਘੜੀਆਂ = ੧ ਪਹਰ।੮ ਪਹਰ = ੧ ਦਿਨ ਰਾਤ। ੧੫ ਥਿਤਾਂ; ੭ ਵਾਰ; ੧੨ ਮਹੀਨੇ, ਛੇ ਰੁੱਤਾਂ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "kirtan-sohila-19", gurmukhi = "ਸੂਰਜੁ; ਏਕੋ ਰੁਤਿ ਅਨੇਕ ॥ ਨਾਨਕ ਕਰਤੇ ਕੇ ਕੇਤੇ ਵੇਸ ॥੨॥੨॥", transliteration = "sooraj; eko rut anek || naanak karte ke kete ves ||2||2||", translation = "And the various seasons originate from the one sun; O Nanak, in just the same way, the many forms originate from the Creator. ||2||2||", hindi = "सूरजु; एको रुति अनेक ॥ नानक करते के केते वेस ॥२॥२॥", punjabi = "ਅਤੇ ਹੋਰ ਅਨੇਕਾਂ ਰੁੱਤਾਂ ਹਨ, ਪਰ ਸੂਰਜ ਇਕੋ ਹੀ ਹੈ (ਜਿਸ ਦੇ ਇਹ ਸਾਰੇ ਵਖ ਵਖ ਰੂਪ ਹਨ), ਤਿਵੇਂ, ਹੇ ਨਾਨਕ! ਕਰਤਾਰ ਦੇ (ਇਹ ਸਾਰੇ ਸਿਧਾਂਤ ਆਦਿਕ) ਅਨੇਕਾਂ ਸਰੂਪ ਹਨ ॥੨॥੨॥", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "kirtan-sohila-20", gurmukhi = "ਰਾਗੁ ਧਨਾਸਰੀ ਮਹਲਾ ੧ ॥", transliteration = "raag dhnaasree mahlaa 1 ||", translation = "Raag Dhanaasaree, First Mehl:", hindi = "रागु धनासरी महला १ ॥", punjabi = "ਰਾਗ ਧਨਾਸਰੀ ਵਿੱਚ ਗੁਰੂ ਨਾਨਕ ਜੀ ਦੀ ਬਾਣੀ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "kirtan-sohila-21", gurmukhi = "ਗਗਨ ਮੈ ਥਾਲੁ. ਰਵਿ ਚੰਦੁ ਦੀਪਕ ਬਨੇ; ਤਾਰਿਕਾ ਮੰਡਲ, ਜਨਕ ਮੋਤੀ ॥", transliteration = "gagan mai thaal. rav chand deepak bne; taarikaa mandal, janak motee ||", translation = "Upon that cosmic plate of the sky, the sun and the moon are the lamps. The stars and their orbs are the studded pearls.", hindi = "गगन मै थालु. रवि चंदु दीपक बने; तारिका मंडल, जनक मोती ॥", punjabi = "ਸਾਰਾ ਆਕਾਸ਼ (ਮਾਨੋ) ਥਾਲ ਹੈ ਤੇ ਸੂਰਜ ਤੇ ਚੰਦ (ਉਸ ਥਾਲ ਵਿਚ) ਦੀਵੇ ਬਣੇ ਹੋਏ ਹਨ। ਤਾਰਿਆਂ ਦੇ ਸਮੂਹ, ਮਾਨੋ, (ਥਾਲ ਵਿਚ) ਮੋਤੀ ਰੱਖੇ ਹੋਏ ਹਨ।", wordMeaning = "ਗਗਨ = ਆਕਾਸ਼। ਗਗਨ ਮੈ = ਗਗਨ ਮਯ, ਆਕਾਸ਼ ਰੂਪ, ਸਾਰਾ ਆਕਾਸ਼। ਰਵਿ = ਸੂਰਜ। ਦੀਪਕ = ਦੀਵੇ। ਜਨਕ = ਜਾਣੋ, ਮਾਨੋ, ਜਿਵੇਂ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "kirtan-sohila-22", gurmukhi = "ਧੂਪੁ ਮਲਆਨਲੋ, ਪਵਣੁ ਚਵਰੋ ਕਰੇ; ਸਗਲ ਬਨਰਾਇ, ਫੂਲੰਤ ਜੋਤੀ ॥੧॥", transliteration = "dhoop malaanlo, pavan chavro kre; sagal banraai, phoolant jotee ||1||", translation = "The fragrance of sandalwood in the air is the temple incense, and the wind is the fan. All the plants of the world are the altar flowers in offering to You, O Luminous Lord. ||1||", hindi = "धूपु मलआनलो, पवणु चवरो करे; सगल बनराइ, फूलंत जोती ॥१॥", punjabi = "ਮਲਯ ਪਰਬਤ ਵਲੋਂ ਆਉਣ ਵਾਲੀ ਹਵਾ, ਮਾਨੋ, ਧੂਪ (ਧੁਖ ਰਿਹਾ) ਹੈ, ਤੇ ਹਵਾ ਚੌਰ ਕਰ ਰਹੀ ਹੈ। ਸਾਰੀ ਬਨਸਪਤੀ ਜੋਤਿ-ਰੂਪ (ਪ੍ਰਭੂ ਦੀ ਆਰਤੀ) ਵਾਸਤੇ ਫੁੱਲ ਦੇ ਰਹੀ ਹੈ ॥੧॥", wordMeaning = "ਮਲਆਨਲੋ = {ਮਲਯ-ਅਨਲੋ} ਮਲਯ ਪਹਾੜ ਵਲੋਂ ਆਉਣ ਵਾਲੀ ਹਵਾ (ਅਨਲ = ਹਵਾ)। ਮਲਯ ਪਰਬਤ ਉਤੇ ਚੰਦਨ ਦੇ ਬੂਟੇ ਹੋਣ ਕਰਕੇ ਉਧਰੋਂ ਆਉਣ ਵਾਲੀ ਹਵਾ ਸੁਗੰਧੀ ਵਾਲੀ ਹੁੰਦੀ ਹੈ। ਮਲਯ ਪਹਾੜ ਭਾਰਤ ਦੇ ਦੱਖਣ ਵਿਚ ਹੈ। ਸਗਲ = ਸਾਰੀ। ਬਨਰਇ = ਬਨਸਪਤੀ। ਫੂਲੰਤ = ਫੁੱਲ ਦੇ ਰਹੀ ਹੈ। ਜੋਤੀ = ਜੋਤਿ-ਰੂਪ ਪ੍ਰਭੂ॥੧॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "kirtan-sohila-23", gurmukhi = "ਕੈਸੀ; ਆਰਤੀ ਹੋਇ ॥ ਭਵ ਖੰਡਨਾ; ਤੇਰੀ ਆਰਤੀ ॥", transliteration = "kaisee; aartee hoi || bhav khandnaa; teree aartee ||", translation = "What a beautiful Aartee, lamp-lit worship service this is! O Destroyer of Fear, this is Your Ceremony of Light.", hindi = "कैसी; आरती होइ ॥ भव खंडना; तेरी आरती ॥", punjabi = "(ਕੁਦਰਤਿ ਵਿਚ) ਤੇਰੀ ਕੈਸੀ ਸੁੰਦਰ ਆਰਤੀ ਹੋ ਰਹੀ ਹੈ! ਹੇ ਜੀਵਾਂ ਦੇ ਜਨਮ ਮਰਨ ਨਾਸ ਕਰਨ ਵਾਲੇ! ਇਹ ਹੈ ਤੇਰੀ ਅਦਭੁਤ ਆਰਤੀ!", wordMeaning = "ਭਵ ਖੰਡਨ = ਹੇ ਜਨਮ ਮਰਨ ਕੱਟਣ ਵਾਲੇ!", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "kirtan-sohila-24", gurmukhi = "ਅਨਹਤਾ ਸਬਦ; ਵਾਜੰਤ ਭੇਰੀ ॥੧॥ ਰਹਾਉ ॥", transliteration = "anahtaa sabad; vaajant bheree ||1|| rhaau ||", translation = "The Unstruck Sound-current of the Shabad is the vibration of the temple drums. ||1||Pause||", hindi = "अनहता सबद; वाजंत भेरी ॥१॥ रहाउ ॥", punjabi = "(ਸਭ ਜੀਵਾਂ ਵਿਚ ਰੁਮਕ ਰਹੀ) ਇੱਕੋ ਜੀਵਨ-ਰੌ, ਮਾਨੋ, ਤੇਰੀ ਆਰਤੀ ਵਾਸਤੇ ਨਾਗਾਰੇ ਵੱਜ ਰਹੇ ਹਨ ॥੧॥ ਰਹਾਉ ॥", wordMeaning = "ਅਨਹਤਾ = {ਅਨ-ਹਤ} ਜੋ ਬਿਨਾ ਵਜਾਏ ਵੱਜੇ, ਇੱਕ-ਰਸ। ਸ਼ਬਦ = ਆਵਾਜ਼, ਜੀਵਨ-ਰੌ। ਭੇਰੀ = ਡੱਫ, ਨਗਾਰਾ॥੧॥ਰਹਾਉ॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "kirtan-sohila-25", gurmukhi = "ਸਹਸ ਤਵ ਨੈਨ, ਨਨ ਨੈਨ ਹਹਿ ਤੋਹਿ ਕਉ; ਸਹਸ ਮੂਰਤਿ, ਨਨਾ ਏਕ ਤੋੁਹੀ ॥", transliteration = "sahas tav nain, nan nain hah toh kau; sahas moorat, nnaa ek touhee ||", translation = "You have thousands of eyes, and yet You have no eyes. You have thousands of forms, and yet You do not have even one.", hindi = "सहस तव नैन, नन नैन हहि तोहि कउ; सहस मूरति, नना एक तोुही ॥", punjabi = "(ਸਭ ਜੀਵਾਂ ਵਿਚ ਵਿਆਪਕ ਹੋਣ ਕਰਕੇ) ਹਜ਼ਾਰਾਂ ਤੇਰੀਆਂ ਅੱਖਾਂ ਹਨ (ਪਰ, ਨਿਰਾਕਾਰ ਹੋਣ ਕਰਕੇ, ਹੇ ਪ੍ਰਭੂ!) ਤੇਰੀਆਂ ਕੋਈ ਅੱਖਾਂ ਨਹੀਂ। ਹਜ਼ਾਰਾਂ ਤੇਰੀਆਂ ਸ਼ਕਲਾਂ ਹਨ, ਪਰ ਤੇਰੀ ਕੋਈ ਭੀ ਸ਼ਕਲ ਨਹੀਂ ਹੈ।", wordMeaning = "ਸਹਸ = ਹਜ਼ਾਰਾਂ। ਤਵ = ਤੇਰੇ। ਨੈਨ = ਅੱਖਾਂ। ਨਨ = ਕੋਈ ਨਹੀਂ। ਹਹਿ = {'ਹੈ' ਤੋਂ ਬਹੁ-ਵਚਨ}। ਤੋਹਿ ਕਉ = ਤੇਰੇ, ਤੈਨੂੰ, ਤੇਰੇ ਵਾਸਤੇ। ਮੂਰਤਿ = ਸ਼ਕਲ। ਨਾ = ਕੋਈ ਨਹੀਂ। ਤਹੀ = ਤੇਰੀ {ਅੱਖਰ 'ਤ' ਦੇ ਨਾਲ ਦੋ ਲਗਾਂ ਹਨ: (ੋ) ਅਤੇ (ੁ) ਅਸਲ ਲਫ਼ਜ਼ 'ਤੁਹੀ' ਹੈ, ਇਥੇ 'ਤੋਹੀ' ਪੜ੍ਹਨਾ ਹੈ}।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "kirtan-sohila-26", gurmukhi = "ਸਹਸ ਪਦ ਬਿਮਲ, ਨਨ ਏਕ ਪਦ; ਗੰਧ ਬਿਨੁ, ਸਹਸ ਤਵ ਗੰਧ; ਇਵ ਚਲਤ ਮੋਹੀ ॥੨॥", transliteration = "sahas pad bimal, nan ek pad; gandh bin, sahas tav gandh; iv chalat mohee ||2||", translation = "You have thousands of Lotus Feet, and yet You do not have even one foot. You have no nose, but you have thousands of noses. This Play of Yours entrances me. ||2||", hindi = "सहस पद बिमल, नन एक पद; गंध बिनु, सहस तव गंध; इव चलत मोही ॥२॥", punjabi = "ਹਜ਼ਾਰਾਂ ਤੇਰੇ ਸੋਹਣੇ ਪੈਰ ਹਨ, (ਪਰ ਨਿਰਾਕਾਰ ਹੋਣ ਕਰਕੇ) ਤੇਰਾ ਇੱਕ ਭੀ ਪੈਰ ਨਹੀਂ। ਹਜ਼ਾਰਾਂ ਤੇਰੇ ਨੱਕ ਹਨ, ਪਰ ਤੂੰ ਨੱਕ ਤੋਂ ਬਿਨਾ ਹੀ ਹੈਂ। ਤੇਰੇ ਅਜੇਹੇ ਕੌਤਕਾਂ ਨੇ ਮੈਨੂੰ ਹੈਰਾਨ ਕੀਤਾ ਹੋਇਆ ਹੈ ॥੨॥", wordMeaning = "ਪਦ = ਪੈਰ। ਬਿਮਲ = ਸਾਫ਼। ਗੰਧ = ਨੱਕ। ਤਿਵ = ਇਸ ਤਰ੍ਹਾਂ। ਚਲਤ = ਕੌਤਕ, ਅਚਰਜ ਖੇਡ॥੨॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "kirtan-sohila-27", gurmukhi = "ਸਭ ਮਹਿ ਜੋਤਿ; ਜੋਤਿ ਹੈ ਸੋਇ ॥", transliteration = "sabh mah jot; jot hai soi ||", translation = "Amongst all is the Light-You are that Light.", hindi = "सभ महि जोति; जोति है सोइ ॥", punjabi = "ਸਾਰੇ ਜੀਵਾਂ ਵਿਚ ਇਕੋ ਉਹੀ ਪਰਮਾਤਮਾ ਦੀ ਜੋਤੀ ਵਰਤ ਰਹੀ ਹੈ।", wordMeaning = "ਜੋਤਿ = ਚਾਨਣ, ਪ੍ਰਕਾਸ਼। ਸੋਇ = ਉਹ ਪ੍ਰਭੂ।", startsAtMs = 0L, endsAtMs = 0L),
