    BaniLine(id = "kirtan-sohila-30", gurmukhi = "ਜੋ ਤਿਸੁ ਭਾਵੈ; ਸੁ ਆਰਤੀ ਹੋਇ ॥੩॥", transliteration = "jo tis bhaavai; su aartee hoi ||3||", translation = "That which is pleasing to Him is the lamp-lit worship service. ||3||", hindi = "जो तिसु भावै; सु आरती होइ ॥३॥", punjabi = "(ਇਸ ਸਰਬ-ਵਿਆਪਕ ਜੋਤਿ ਦੀ) ਆਰਤੀ ਇਹ ਹੈ ਕਿ ਜੋ ਕੁਝ ਉਸ ਦੀ ਰਜ਼ਾ ਵਿਚ ਹੋ ਰਿਹਾ ਹੈ, ਉਹ ਜੀਵ ਨੂੰ ਚੰਗਾ ਲੱਗੇ (ਪ੍ਰਭੂ ਦੀ ਰਜ਼ਾ ਵਿਚ ਤੁਰਨਾ ਪ੍ਰਭੂ ਦੀ ਆਰਤੀ ਕਰਨੀ ਹੈ) ॥੩॥", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "kirtan-sohila-31", gurmukhi = "ਹਰਿ ਚਰਣ ਕਵਲ ਮਕਰੰਦ, ਲੋਭਿਤ ਮਨੋ; ਅਨਦਿਨੋੁ, ਮੋਹਿ ਆਹੀ ਪਿਆਸਾ ॥", transliteration = "har charan kaval makarand, lobhit mno; andino, moh aahee piaasaa ||", translation = "My mind is enticed by the honey-sweet Lotus Feet of the Lord. Day and night, I thirst for them.", hindi = "हरि चरण कवल मकरंद, लोभित मनो; अनदिनोु, मोहि आही पिआसा ॥", punjabi = "ਹੇ ਹਰੀ! ਤੇਰੇ ਚਰਨ-ਰੂਪ ਕੌਲ-ਫੁੱਲਾਂ ਦੇ ਰਸ ਲਈ ਮੇਰਾ ਮਨ ਲਲਚਾਂਦਾ ਹੈ, ਹਰ ਰੋਜ਼ ਮੈਨੂੰ ਇਸੇ ਰਸ ਦੀ ਪਿਆਸ ਲੱਗੀ ਹੋਈ ਹੈ।", wordMeaning = "ਮਕਰੰਦ = ਫੁੱਲਾਂ ਦੀ ਵਿਚਲੀ ਧੂੜ {Pollen-dust}, ਫੁੱਲਾਂ ਦਾ ਰਸ। ਮਨੋ = ਮਨ। ਅਨਦਿਨ = {ਅੱਖਰ 'ਨ' ਦੇ ਨਾਲ ਦੋ ਲਗਾਂ ਹਨ: (ੋ) ਅਤੇ (ੁ) ਅਸਲ ਲਫ਼ਜ਼ 'ਅਨਦਿਨੁ' ਹੈ, ਇਥੇ 'ਅਨਦਿਨੋ' ਪੜ੍ਹਨਾ ਹੈ} ਹਰ ਰੋਜ਼। ਮੋਹਿ = ਮੈਨੂੰ। ਆਹੀ = ਹੈ, ਰਹਿੰਦੀ ਹੈ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "kirtan-sohila-32", gurmukhi = "ਕ੍ਰਿਪਾ ਜਲੁ ਦੇਹਿ, ਨਾਨਕ ਸਾਰਿੰਗ ਕਉ; ਹੋਇ ਜਾ ਤੇ. ਤੇਰੈ ਨਾਇ ਵਾਸਾ ॥੪॥੩॥", transliteration = "kripaa jal deh, naanak saaring kau; hoi jaa te. terai naai vaasaa ||4||3||", translation = "Bestow the Water of Your Mercy upon Nanak, the thirsty song-bird, so that he may come to dwell in Your Name. ||4||3||", hindi = "क्रिपा जलु देहि, नानक सारिंग कउ; होइ जा ते. तेरै नाइ वासा ॥४॥३॥", punjabi = "ਮੈਨੂੰ ਨਾਨਕ ਪਪੀਹੇ ਨੂੰ ਆਪਣੀ ਮਿਹਰ ਦਾ ਜਲ ਦੇਹ, ਜਿਸ (ਦੀ ਬਰਕਤਿ) ਨਾਲ ਮੈਂ ਤੇਰੇ ਨਾਮ ਵਿਚ ਟਿਕਿਆ ਰਹਾਂ ॥੪॥੩॥", wordMeaning = "ਸਾਰਿੰਗ = ਪਪੀਹਾ। ਕਉ = ਨੂੰ। ਜਾ ਤੇ = ਜਿਸ ਤੋਂ, ਜਿਸ ਨਾਲ। ਤੇਰੈ ਨਾਇ = ਤੇਰੇ ਨਾਮ ਵਿਚ॥੪॥", startsAtMs = 0L, endsAtMs = 0L)
)

