    BaniLine(id = "kirtan-sohila-37", gurmukhi = "ਕਰਿ ਡੰਡਉਤ; ਪੁਨੁ ਵਡਾ ਹੇ ॥੧॥ ਰਹਾਉ ॥", transliteration = "kar dandaut; pun vdaa he ||1|| rhaau ||", translation = "Bow down before Him; this is a virtuous action indeed. ||1||Pause||", hindi = "करि डंडउत; पुनु वडा हे ॥१॥ रहाउ ॥", punjabi = "ਗੁਰੂ ਅੱਗੇ ਢਹਿ ਪਉ, ਇਹ ਬੜਾ ਨੇਕ ਕੰਮ ਹੈ ॥੧॥ ਰਹਾਉ ॥", wordMeaning = "ਪੁਨੁ = ਭਲਾ ਕੰਮ। ਡੰਡਉਤ = ਲੰਮੇ ਪੈ ਕੇ ਨਮਸ-ਕਾਰ॥੧॥ਰਹਾਉ॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "kirtan-sohila-38", gurmukhi = "ਸਾਕਤ. ਹਰਿ ਰਸ ਸਾਦੁ. ਨ ਜਾਣਿਆ; ਤਿਨ ਅੰਤਰਿ. ਹਉਮੈ ਕੰਡਾ ਹੇ ॥", transliteration = "saakat. har ras saad. na jaaniaa; tin antar. haumai kandaa he ||", translation = "The wicked shaaktas, the faithless cynics, do not know the Taste of the Lord's Sublime Essence. The thorn of egotism is embedded deep within them.", hindi = "साकत. हरि रस सादु. न जाणिआ; तिन अंतरि. हउमै कंडा हे ॥", punjabi = "ਜੇਹੜੇ ਮਨੁੱਖ ਪਰਮਾਤਮਾ ਨਾਲੋਂ ਟੁੱਟੇ ਹੋਏ ਹਨ, ਉਹ ਉਸ ਦੇ ਨਾਮ ਦੇ ਰਸ ਦੇ ਸੁਆਦ ਨੂੰ ਸਮਝ ਨਹੀਂ ਸਕਦੇ। ਉਹਨਾਂ ਦੇ ਮਨ ਵਿਚ ਅਹੰਕਾਰ ਦਾ (ਮਾਨੋ) ਕੰਡਾ ਚੁੱਭਾ ਹੋਇਆ ਹੈ।", wordMeaning = "ਸਾਕਤ = ਰੱਬ ਨਾਲੋਂ ਟੁੱਟੇ ਹੋਏ ਮਨੁੱਖ। ਸਾਦੁ = ਸੁਆਦ। ਤਿਨ ਅੰਤਰਿ = ਉਹਨਾਂ ਦੇ ਅੰਦਰ, ਉਹਨਾਂ ਦੇ ਮਨ ਵਿਚ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "kirtan-sohila-39", gurmukhi = "ਜਿਉ ਜਿਉ ਚਲਹਿ, ਚੁਭੈ ਦੁਖੁ ਪਾਵਹਿ; ਜਮਕਾਲੁ ਸਹਹਿ ਸਿਰਿ ਡੰਡਾ ਹੇ ॥੨॥", transliteration = "jiu jiu chalah, chubhai dukh paavah; jamkaal sahah sir dandaa he ||2||", translation = "The more they walk away, the deeper it pierces them, and the more they suffer in pain, until finally, the Messenger of Death smashes his club against their heads. ||2||", hindi = "जिउ जिउ चलहि, चुभै दुखु पावहि; जमकालु सहहि सिरि डंडा हे ॥२॥", punjabi = "ਜਿਉਂ ਜਿਉਂ ਉਹ ਤੁਰਦੇ ਹਨ (ਜਿਉਂ ਜਿਉਂ ਉਹ ਹਉਮੈ ਦੇ ਸੁਭਾਵ ਵਾਲੀ ਵਰਤੋਂ ਵਰਤਦੇ ਹਨ, ਹਉਮੈ ਦਾ ਉਹ ਕੰਡਾ ਉਹਨਾਂ ਨੂੰ) ਚੁੱਭਦਾ ਹੈ, ਉਹ ਦੁੱਖ ਪਾਂਦੇ ਹਨ, ਅਤੇ ਆਪਣੇ ਸਿਰ ਉੱਤੇ ਆਤਮਕ ਮੌਤ-ਰੂਪ ਡੰਡਾ ਸਹਾਰਦੇ ਹਨ (ਆਤਮਕ ਮੌਤ ਉਹਨਾਂ ਦੇ ਸਿਰ ਉਤੇ ਸਵਾਰ ਰਹਿੰਦੀ ਹੈ) ॥੨॥", wordMeaning = "ਚਲਹਿ = ਤੁਰਦੇ ਹਨ। ਚੁਭੈ = (ਕੰਡਾ) ਚੁੱਭਦਾ ਹੈ। ਜਮ ਕਾਲੁ = (ਆਤਮਕ) ਮੌਤ। ਸਿਰਿ = ਸਿਰ ਉੱਤੇ॥੨॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "kirtan-sohila-40", gurmukhi = "ਹਰਿ ਜਨ, ਹਰਿ ਹਰਿ ਨਾਮਿ ਸਮਾਣੇ; ਦੁਖੁ ਜਨਮ ਮਰਣ ਭਵ ਖੰਡਾ ਹੇ ॥", transliteration = "har jan, har har naam smaane; dukh janam maran bhav khandaa he ||", translation = "The humble servants of the Lord are absorbed in the Name of the Lord, Har, Har. The pain of birth and the fear of death are eradicated.", hindi = "हरि जन, हरि हरि नामि समाणे; दुखु जनम मरण भव खंडा हे ॥", punjabi = "(ਦੂਜੇ ਪਾਸੇ) ਪਰਮਾਤਮਾ ਦੇ ਪਿਆਰੇ ਬੰਦੇ ਪਰਮਾਤਮਾ ਦੇ ਨਾਮ ਵਿਚ ਜੁੜੇ ਰਹਿੰਦੇ ਹਨ। ਉਹਨਾਂ ਦਾ ਸੰਸਾਰ ਦਾ ਜੰਮਣ ਮਰਨ ਦਾ ਦੁੱਖ ਕੱਟਿਆ ਜਾਂਦਾ ਹੈ।", wordMeaning = "ਨਾਮਿ = ਨਾਮ ਵਿਚ। ਸਮਾਣੇ = ਲੀਨ, ਮਸਤ। ਭਵ = ਸੰਸਾਰ। ਖੰਡਾ ਹੇ = ਨਾਸ ਕਰ ਲਿਆ ਹੈ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "kirtan-sohila-41", gurmukhi = "ਅਬਿਨਾਸੀ ਪੁਰਖੁ ਪਾਇਆ ਪਰਮੇਸਰੁ; ਬਹੁ ਸੋਭ ਖੰਡ ਬ੍ਰਹਮੰਡਾ ਹੇ ॥੩॥", transliteration = "abinaasee purakh paaiaa parmesar; bah sobh khand brahamandaa he ||3||", translation = "They have found the Imperishable Supreme Being, the Transcendent Lord God, and they receive great honor throughout all the worlds and realms. ||3||", hindi = "अबिनासी पुरखु पाइआ परमेसरु; बहु सोभ खंड ब्रहमंडा हे ॥३॥", punjabi = "ਉਹਨਾਂ ਨੂੰ ਕਦੇ ਨਾਸ਼ ਨਾਹ ਹੋਣ ਵਾਲਾ ਸਰਬ-ਵਿਆਪਕ ਪਰਮੇਸਰ ਮਿਲ ਪੈਂਦਾ ਹੈ। ਉਹਨਾਂ ਦੀ ਸੋਭਾ ਸਾਰੇ ਖੰਡਾਂ ਬ੍ਰਹਮੰਡਾਂ ਵਿਚ ਹੋ ਜਾਂਦੀ ਹੈ ॥੩॥", wordMeaning = "ਸੋਭ = ਸੋਭਾ। ਖੰਡ ਬ੍ਰਹਮੰਡਾ = ਸਾਰੇ ਜਗਤ ਵਿਚ॥੩॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "kirtan-sohila-42", gurmukhi = "ਹਮ ਗਰੀਬ ਮਸਕੀਨ ਪ੍ਰਭ ਤੇਰੇ; ਹਰਿ ਰਾਖੁ ਰਾਖੁ ਵਡ ਵਡਾ ਹੇ ॥", transliteration = "ham greeb maskeen prabh tere; har raakh raakh vad vdaa he ||", translation = "I am poor and meek, God, but I belong to You! Save me-please save me, O Greatest of the Great!", hindi = "हम गरीब मसकीन प्रभ तेरे; हरि राखु राखु वड वडा हे ॥", punjabi = "ਹੇ ਪ੍ਰਭੂ! ਅਸੀਂ ਜੀਵ ਤੇਰੇ ਦਰ ਦੇ ਗਰੀਬ ਮੰਗਦੇ ਹਾਂ। ਤੂੰ ਸਭ ਤੋਂ ਵੱਡਾ ਸਹਾਈ ਹੈਂ। ਸਾਨੂੰ (ਇਹਨਾਂ ਕਾਮਾਦਿਕਾਂ ਤੋਂ) ਬਚਾ ਲੈ।", wordMeaning = "ਮਸਕੀਨ = ਆਜਿਜ਼। ਪ੍ਰਭ = ਹੇ ਪ੍ਰਭੂ। ਰਾਖੁ = ਰੱਖਿਆ ਕਰ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "kirtan-sohila-43", gurmukhi = "ਜਨ ਨਾਨਕ. ਨਾਮੁ ਅਧਾਰੁ ਟੇਕ ਹੈ; ਹਰਿ ਨਾਮੇ ਹੀ ਸੁਖੁ ਮੰਡਾ ਹੇ ॥੪॥੪॥", transliteration = "jan naanak. naam adhaar tek hai; har naame hee sukh mandaa he ||4||4||", translation = "Servant Nanak takes the Sustenance and Support of the Naam. In the Name of the Lord, he enjoys celestial peace. ||4||4||", hindi = "जन नानक. नामु अधारु टेक है; हरि नामे ही सुखु मंडा हे ॥४॥४॥", punjabi = "ਹੇ ਪ੍ਰਭੂ! ਤੇਰੇ ਦਾਸ ਨਾਨਕ ਨੂੰ ਤੇਰਾ ਨਾਮ ਹੀ ਆਸਰਾ ਹੈ, ਤੇਰਾ ਨਾਮ ਹੀ ਸਹਾਰਾ ਹੈ। ਤੇਰੇ ਨਾਮ ਵਿਚ ਜੁੜਿਆਂ ਹੀ ਸੁਖ ਮਿਲਦਾ ਹੈ ॥੪॥੪॥", wordMeaning = "ਅਧਾਰੁ = ਆਸਰਾ। ਨਾਮੇ = ਨਾਮਿ ਹੀ, ਨਾਮ ਵਿਚ ਹੀ। ਮੰਡਾ = ਮਿਲਿਆ॥੪॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "kirtan-sohila-44", gurmukhi = "ਰਾਗੁ ਗਉੜੀ ਪੂਰਬੀ ਮਹਲਾ ੫ ॥", transliteration = "raag gauree poorbee mahlaa 5 ||", translation = "Raag Gauree Poorbee, Fifth Mehl:", hindi = "रागु गउड़ी पूरबी महला ५ ॥", punjabi = "ਗਉੜੀ ਪੂਰਬੀ ਰਾਗ, ਪੰਜਵੀਂ ਪਾਤਸ਼ਾਹੀ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "kirtan-sohila-45", gurmukhi = "ਕਰਉ ਬੇਨੰਤੀ, ਸੁਣਹੁ ਮੇਰੇ ਮੀਤਾ; ਸੰਤ ਟਹਲ ਕੀ ਬੇਲਾ ॥", transliteration = "karau benantee, sunah mere meetaa; sant tahal kee belaa ||", translation = "Listen, my friends, I beg of you: now is the time to serve the Saints!", hindi = "करउ बेनंती, सुणहु मेरे मीता; संत टहल की बेला ॥", punjabi = "ਹੇ ਮੇਰੇ ਮਿੱਤਰੋ! ਸੁਣੋ! ਮੈਂ ਬੇਨਤੀ ਕਰਦਾ ਹਾਂ-(ਹੁਣ) ਗੁਰਮੁਖਾਂ ਦੀ ਸੇਵਾ ਕਰਨ ਦਾ ਵੇਲਾ ਹੈ।", wordMeaning = "ਕਰਉ = ਕਰਉਂ, ਮੈਂ ਕਰਦਾ ਹਾਂ {ਵਰਤਮਾਨ ਕਾਲ, ਉੱਤਮ ਪੁਰਖ, ਇਕ-ਵਚਨ}। ਸੁਣਹੁ = ਤੁਸੀ ਸੁਣੋ {ਹੁਕਮੀ ਭਵਿੱਖਤ, ਮੱਧਮ ਪੁਰਖ, ਬਹੁ-ਵਚਨ}। ਬੇਲਾ = ਵੇਲਾ, ਮੌਕਾ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "kirtan-sohila-46", gurmukhi = "ਈਹਾ ਖਾਟਿ ਚਲਹੁ, ਹਰਿ ਲਾਹਾ; ਆਗੈ ਬਸਨੁ ਸੁਹੇਲਾ ॥੧॥", transliteration = "eehaa khaat chalah, har laahaa; aagai basan suhelaa ||1||", translation = "In this world, earn the profit of the Lord's Name, and hereafter, you shall dwell in peace. ||1||", hindi = "ईहा खाटि चलहु, हरि लाहा; आगै बसनु सुहेला ॥१॥", punjabi = "(ਜੇ ਸੇਵਾ ਕਰੋਗੇ, ਤਾਂ) ਇਸ ਜਨਮ ਵਿਚ ਪ੍ਰਭੂ ਦੇ ਨਾਮ ਦੀ ਖੱਟੀ ਖੱਟ ਕੇ ਜਾਵੋਗੇ, ਅਤੇ ਪਰਲੋਕ ਵਿਚ ਰਹਿਣਾ ਸੌਖਾ ਹੋ ਜਾਇਗਾ ॥੧॥", wordMeaning = "ਈਹਾ = ਇਥੇ, ਇਸ ਜਨਮ ਵਿਚ। ਖਾਟਿ = ਖੱਟ ਕੇ। ਲਾਹਾ = ਲਾਭ, ਖੱਟੀ। ਆਗੈ = ਪਰਲੋਕ ਵਿਚ। ਬਸਨੁ = ਵੱਸਣਾ, ਵਸੋਂ। ਸੁਹੇਲਾ = ਸੌਖਾ॥੧॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "kirtan-sohila-47", gurmukhi = "ਅਉਧ ਘਟੈ; ਦਿਨਸੁ ਰੈਣਾਰੇ ॥", transliteration = "audh ghtai; dinas rainaare ||", translation = "This life is diminishing, day and night.", hindi = "अउध घटै; दिनसु रैणारे ॥", punjabi = "ਹੇ ਮਨ! ਦਿਨ ਰਾਤ (ਬੀਤ ਬੀਤ ਕੇ) ਉਮਰ ਘਟਦੀ ਜਾ ਰਹੀ ਹੈ।", wordMeaning = "ਅਉਧ = ਉਮਰ। ਰੈਣਾ = ਰਾਤ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "kirtan-sohila-48", gurmukhi = "ਮਨ ਗੁਰ ਮਿਲਿ; ਕਾਜ ਸਵਾਰੇ ॥੧॥ ਰਹਾਉ ॥", transliteration = "man gur mil; kaaj svaare ||1|| rhaau ||", translation = "Meeting with the Guru, your affairs shall be resolved. ||1||Pause||", hindi = "मन गुर मिलि; काज सवारे ॥१॥ रहाउ ॥", punjabi = "ਹੇ (ਮੇਰੇ) ਮਨ! ਗੁਰੂ ਨੂੰ ਮਿਲ ਕੇ (ਮਨੁੱਖਾ ਜੀਵਨ ਦਾ) ਕੰਮ ਸਿਰੇ ਚਾੜ੍ਹ ॥੧॥ ਰਹਾਉ ॥", wordMeaning = "ਮਨ = ਹੇ ਮਨ! ਮਿਲਿ = ਮਿਲ ਕੇ। ਸਵਾਰੇ = ਸਵਾਰਿ, ਸਵਾਰ ਲੈ॥੧॥ਰਹਾਉ॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "kirtan-sohila-49", gurmukhi = "ਇਹੁ ਸੰਸਾਰੁ ਬਿਕਾਰੁ ਸੰਸੇ ਮਹਿ; ਤਰਿਓ ਬ੍ਰਹਮ ਗਿਆਨੀ ॥", transliteration = "ih sansaar bikaar sanse mah; trio braham giaanee ||", translation = "This world is engrossed in corruption and cynicism. Only those who know God are saved.", hindi = "इहु संसारु बिकारु संसे महि; तरिओ ब्रहम गिआनी ॥", punjabi = "ਇਹ ਜਗਤ ਵਿਕਾਰਾਂ ਨਾਲ ਭਰਪੂਰ ਹੈ। (ਜਗਤ ਦੇ ਜੀਵ) ਤੌਖ਼ਲਿਆਂ ਵਿਚ (ਡੁੱਬ ਰਹੇ ਹਨ। ਇਹਨਾਂ ਵਿਚੋਂ) ਉਹੀ ਮਨੁੱਖ ਨਿਕਲਦਾ ਹੈ ਜਿਸ ਨੇ ਪਰਮਾਤਮਾ ਨਾਲ ਜਾਣ-ਪਛਾਣ ਪਾ ਲਈ ਹੈ।", wordMeaning = "ਬਿਕਾਰ = ਵਿਕਾਰ-ਰੂਪ, ਵਿਕਾਰਾਂ ਨਾਲ ਭਰਿਆ ਹੋਇਆ। ਸੰਸੇ ਮਹਿ = ਸਹਿੰਸਿਆਂ ਵਿਚ, ਤੌਖ਼ਲਿਆਂ ਵਿਚ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "kirtan-sohila-50", gurmukhi = "ਜਿਸਹਿ ਜਗਾਇ, ਪੀਆਵੈ ਇਹੁ ਰਸੁ; ਅਕਥ ਕਥਾ ਤਿਨਿ ਜਾਨੀ ॥੨॥", transliteration = "jisah jgaai, peeaavai ih ras; akath kthaa tin jaanee ||2||", translation = "Only those who are awakened by the Lord to drink in this Sublime Essence, come to know the Unspoken Speech of the Lord. ||2||", hindi = "जिसहि जगाइ, पीआवै इहु रसु; अकथ कथा तिनि जानी ॥२॥", punjabi = "(ਵਿਕਾਰਾਂ ਵਿਚ ਸੁੱਤੇ ਹੋਏ) ਜਿਸ ਮਨੁੱਖ ਨੂੰ ਪ੍ਰਭੂ ਆਪ ਜਗਾ ਕੇ ਇਹ ਨਾਮ-ਅੰਮ੍ਰਿਤ ਪਿਲਾਂਦਾ ਹੈ, ਉਸ ਮਨੁੱਖ ਨੇ ਅਕੱਥ ਪ੍ਰਭੂ ਦੀਆਂ ਗੱਲਾਂ (ਬੇਅੰਤ ਗੁਣਾਂ ਵਾਲੇ ਪ੍ਰਭੂ ਦੀ ਸਿਫ਼ਤ-ਸਾਲਾਹ) ਕਰਨ ਦੀ ਜਾਚ ਸਿੱਖ ਲਈ ਹੈ ॥੨॥", wordMeaning = "ਜਿਸਹਿ = ਜਿਸ ਮਨੁੱਖ ਨੂੰ। ਜਗਾਇ = ਜਗਾ ਕੇ। ਪੀਆਵੈ = ਪਿਲਾਂਦਾ ਹੈ। ਤਿਨਿ = ਉਸ ਨੇ॥੨॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "kirtan-sohila-51", gurmukhi = "ਜਾ ਕਉ ਆਏ. ਸੋਈ ਬਿਹਾਝਹੁ; ਹਰਿ ਗੁਰ ਤੇ. ਮਨਹਿ ਬਸੇਰਾ ॥", transliteration = "jaa kau aae. soee bihaajhah; har gur te. manah bseraa ||", translation = "Purchase only that for which you have come into the world, and through the Guru, the Lord shall dwell within your mind.", hindi = "जा कउ आए. सोई बिहाझहु; हरि गुर ते. मनहि बसेरा ॥", punjabi = "(ਹੇ ਭਾਈ!) ਜਿਸ ਕੰਮ ਵਾਸਤੇ (ਇੱਥੇ) ਆਏ ਹੋ, ਉਸ ਦਾ ਵਣਜ ਕਰੋ। ਉਹ ਹਰਿ-ਨਾਮ ਗੁਰੂ ਦੀ ਰਾਹੀਂ (ਹੀ) ਮਨ ਵਿਚ ਵੱਸ ਸਕਦਾ ਹੈ।", wordMeaning = "ਜਾ ਕਉ = ਜਿਸ (ਮਨੋਰਥ) ਵਾਸਤੇ। ਬਿਹਾਝਹੁ = ਖ਼ਰੀਦੋ, ਵਣਜ ਕਰੋ। ਤੇ = ਤੋਂ, ਦੀ ਰਾਹੀਂ। ਮਨਹਿ = ਮਨ ਵਿਚ ਹੀ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "kirtan-sohila-52", gurmukhi = "ਨਿਜ ਘਰਿ ਮਹਲੁ, ਪਾਵਹੁ ਸੁਖ ਸਹਜੇ; ਬਹੁਰਿ. ਨ ਹੋਇਗੋ ਫੇਰਾ ॥੩॥", transliteration = "nij ghar mahal, paavah sukh sahje; bhur. na hoigo pheraa ||3||", translation = "Within the home of your own inner being, you shall obtain the Mansion of the Lord's Presence with intuitive ease. You shall not be consigned again to the wheel of reincarnation. ||3||", hindi = "निज घरि महलु, पावहु सुख सहजे; बहुरि. न होइगो फेरा ॥३॥", punjabi = "(ਜੇ ਗੁਰੂ ਦੀ ਸਰਨ ਪਵੋਗੇ, ਤਾਂ) ਆਤਮਕ ਆਨੰਦ ਅਤੇ ਅਡੋਲਤਾ ਵਿਚ ਟਿਕ ਕੇ ਆਪਣੇ ਅੰਦਰ ਹੀ ਪਰਮਾਤਮਾ ਦਾ ਟਿਕਾਣਾ ਲੱਭ ਲਵੋਗੇ। ਫਿਰ ਮੁੜ ਜਨਮ ਮਰਨ ਦਾ ਗੇੜ ਨਹੀਂ ਹੋਵੇਗਾ ॥੩॥", wordMeaning = "ਨਿਜ ਘਰਿ = ਆਪਣੇ ਘਰ ਵਿਚ, ਆਪਣੇ ਹਿਰਦੇ ਵਿਚ। ਮਹਲੁ = (ਪਰਮਾਤਮਾ ਦਾ) ਟਿਕਾਣਾ। ਸਹਜੇ = ਸਹਜਿ, ਆਤਮਕ ਅਡੋਲਤਾ ਵਿਚ। ਬਹੁਰਿ = ਫਿਰ॥੩॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "kirtan-sohila-53", gurmukhi = "ਅੰਤਰਜਾਮੀ ਪੁਰਖ ਬਿਧਾਤੇ; ਸਰਧਾ ਮਨ ਕੀ ਪੂਰੇ ॥", transliteration = "antarjaamee purakh bidhaate; sardhaa man kee poore ||", translation = "O Inner-knower, Searcher of Hearts, O Primal Being, Architect of Destiny: please fulfill this yearning of my mind.", hindi = "अंतरजामी पुरख बिधाते; सरधा मन की पूरे ॥", punjabi = "ਹੇ ਹਰੇਕ ਦੇ ਦਿਲ ਦੀ ਜਾਣਨ ਵਾਲੇ ਸਰਬ-ਵਿਆਪਕ ਸਿਰਜਨਹਾਰ! ਮੇਰੇ ਮਨ ਦੀ ਇੱਛਾ ਪੂਰੀ ਕਰ।", wordMeaning = "ਅੰਤਰਜਾਮੀ = ਹੇ ਦਿਲਾਂ ਦੀ ਜਾਣਨ ਵਾਲੇ! ਪੁਰਖ = ਹੇ ਸਭ ਵਿਚ ਵਿਆਪਕ! ਬਿਧਾਤੇ = ਹੇ ਸਿਰਜਣਹਾਰ! ਪੂਰੇ = ਪੂਰਿ, ਪੂਰੀ ਕਰ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "kirtan-sohila-54", gurmukhi = "ਨਾਨਕ ਦਾਸੁ. ਇਹੈ ਸੁਖੁ ਮਾਗੈ; ਮੋ ਕਉ ਕਰਿ ਸੰਤਨ ਕੀ ਧੂਰੇ ॥੪॥੫॥", transliteration = "naanak daas. ihai sukh maagai; mo kau kar santan kee dhoore ||4||5||", translation = "Nanak, Your slave, begs for this happiness: let me be the dust of the feet of the Saints. ||4||5||", hindi = "नानक दासु. इहै सुखु मागै; मो कउ करि संतन की धूरे ॥४॥५॥", punjabi = "ਦਾਸ ਨਾਨਕ ਤੈਥੋਂ ਇਹੀ ਸੁਖ ਮੰਗਦਾ ਹੈ ਕਿ ਮੈਨੂੰ ਸੰਤਾਂ ਦੇ ਚਰਨਾਂ ਦੀ ਧੂੜ ਬਣਾ ਦੇਹ ॥੪॥੫॥", wordMeaning = "ਮਾਗੈ = ਮੰਗਦਾ ਹੈ। ਮੋ ਕਉ = ਮੈਨੂੰ। ਧੂਰੇ = ਚਰਨ-ਧੂੜ॥੪॥", startsAtMs = 0L, endsAtMs = 0L)
)
